# ==============================================================================# 027_AUDIT_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS audit(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    module TEXT,    action TEXT,    username TEXT,    status TEXT)""")conn.commit()def audit(module, action, username="SYSTEM", status="SUCCESS"):    cur.execute(        """        INSERT INTO audit(            timestamp,            module,            action,            username,            status        )        VALUES(?,?,?,?,?)        """,        (            datetime.now().isoformat(),            module,            action,            username,            status        )    )    conn.commit()audit(    "027_AUDIT_ENGINE",    "SYSTEM_INITIALIZATION")cur.execute("""SELECTid,timestamp,module,action,username,statusFROM auditORDER BY id DESCLIMIT 10""")print("="*80)print("AUDIT ENGINE")print("="*80)for row in cur.fetchall():    print(dict(row))print("="*80)conn.close()

